1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="UTF-8" />
5	<meta name="viewport" content="width=device-width, initial-scale=1" />
6	<title>Erasmus – Schkeuditz Vitalis</title>
7	<style>
8	  /* ============================================================
9	     DESIGN TOKENS — EDIT COLORS / FONTS HERE
10	     ============================================================ */
11	  :root{
12	    --c-black:#14100E;      /* near-black, warm tint (Germany: black) */
13	    --c-red:#A9333B;        /* brick/poster red (Germany: red) */
14	    --c-gold:#D3A248;       /* muted gold (Germany: gold) */
15	    --c-white:#F7F1E6;      /* warm paper white (Germany: white) */
16	    --c-stone:#8C8577;      /* neutral stone */
17	    --c-ink:#2B2621;        /* body text on light surfaces */
18	
19	    --font-display:"Iowan Old Style","Palatino Linotype","URW Palladio L",Palatino,Georgia,serif;
20	    --font-body:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;
21	
22	    --nav-h:64px;
23	  }
24	
25	  *{ box-sizing:border-box; }
26	  html,body{
27	    height:100%;
28	    margin:0;
29	    overflow:hidden; /* no page scrolling */
30	    background:var(--c-black);
31	    font-family:var(--font-body);
32	  }
33	  @media (prefers-reduced-motion: reduce){
34	    *{ transition:none !important; animation:none !important; }
35	  }
36	
37	  button{ font:inherit; }
38	
39	  .page{
40	    display:flex;
41	    flex-direction:column;
42	    height:100vh;
43	    height:100dvh;
44	    overflow:hidden;
45	    position:relative;
46	  }
47	
48	  /* ============================================================
49	     BACKGROUND — CSS/SVG "golden-hour Germany" backdrop.
50	     To use a real photo instead: set a background-image on .bg
51	     (e.g. background:url('images/bg-leipzig.jpg') center/cover;)
52	     and remove/hide the <svg class="bg-sky"> below.
53	     ============================================================ */
54	  .bg{ position:fixed; inset:0; z-index:0; }
55	  .bg-sky{ width:100%; height:100%; display:block; }
56	  .bg-overlay{
57	    position:absolute; inset:0;
58	    background:linear-gradient(180deg,
59	      rgba(20,16,14,.60) 0%,
60	      rgba(20,16,14,.22) 32%,
61	      rgba(20,16,14,.30) 60%,
62	      rgba(20,16,14,.72) 100%);
63	  }
64	
65	  /* ============================================================
66	     NAVIGATION
67	     ============================================================ */
68	  .topnav{
69	    position:sticky; top:0; z-index:20;
70	    display:flex; align-items:center; justify-content:space-between;
71	    gap:12px;
72	    min-height:var(--nav-h);
73	    padding:10px clamp(14px,4vw,40px);
74	    background:linear-gradient(180deg, rgba(20,16,14,.92), rgba(20,16,14,.78));
75	    border-bottom:1px solid rgba(211,162,72,.35);
76	    flex-wrap:wrap;
77	  }
78	  .brand{
79	    display:flex; align-items:baseline; gap:.5rem;
80	    color:var(--c-white);
81	    white-space:nowrap;
82	  }
83	  .brand-mark{ color:var(--c-gold); font-size:1.1rem; }
84	  .brand-main{
85	    font-family:var(--font-display); font-weight:700;
86	    font-size:clamp(.95rem,1.6vw,1.15rem); letter-spacing:.01em;
87	  }
88	  .brand-sub{
89	    font-family:var(--font-display); font-style:italic;
90	    color:var(--c-gold); font-size:clamp(.68rem,1.3vw,.8rem);
91	  }
92	
93	  .menu{
94	    list-style:none; display:flex; align-items:center;
95	    gap:clamp(2px,1vw,8px); margin:0; padding:0; flex-wrap:wrap;
96	  }
97	  .menu > li{ position:relative; }
98	  .menu-link{
99	    background:none; border:0; cursor:pointer;
100	    color:var(--c-white);
101	    text-transform:uppercase; letter-spacing:.09em;
102	    font-size:clamp(.68rem,1.3vw,.8rem); font-weight:600;
103	    padding:.55rem .65rem; border-radius:4px;
104	    position:relative;
105	  }
106	  .menu-link::after{
107	    content:""; position:absolute; left:.65rem; right:.65rem; bottom:.3rem;
108	    height:2px; background:var(--c-gold);
109	    transform:scaleX(0); transform-origin:left;
110	    transition:transform .18s ease;
111	  }
112	  .menu-link:hover, .menu-link:focus-visible{ color:var(--c-gold); }
113	  .menu-link[aria-current="page"]::after,
114	  .menu-link.parent-active::after{ transform:scaleX(1); }
115	
116	  .dropdown{
117	    list-style:none; margin:0; padding:.4rem;
118	    position:absolute; top:calc(100% + 8px); left:50%;
119	    transform:translateX(-50%) translateY(-6px);
120	    min-width:150px;
121	    background:var(--c-black);
122	    border:1px solid rgba(211,162,72,.4);
123	    border-radius:6px;
124	    box-shadow:0 14px 34px rgba(0,0,0,.5);
125	    opacity:0; pointer-events:none;
126	    transition:opacity .15s ease, transform .15s ease;
127	  }
128	  .has-dropdown.open .dropdown{
129	    opacity:1; pointer-events:auto;
130	    transform:translateX(-50%) translateY(0);
131	  }
132	  .dropdown-link{
133	    display:block; width:100%; text-align:left;
134	    background:none; border:0; cursor:pointer;
135	    color:var(--c-white); text-transform:none;
136	    font-size:.82rem; letter-spacing:.02em;
137	    padding:.5rem .6rem; border-radius:4px;
138	  }
139	  .dropdown-link:hover, .dropdown-link:focus-visible{
140	    background:rgba(211,162,72,.15); color:var(--c-gold);
141	  }
142	  .dropdown-link[aria-current="page"]{ color:var(--c-gold); font-weight:700; }
143	
144	  @media (max-width:640px){
145	    .menu{ width:100%; justify-content:center; }
146	    .brand{ width:100%; justify-content:center; }
147	    .dropdown{ left:0; transform:translateY(-6px); }
148	    .has-dropdown.open .dropdown{ transform:translateY(0); }
149	  }
150	
151	  /* ============================================================
152	     MAIN / GALLERY VIEWER
153	     ============================================================ */
154	  main.viewer-main{
155	    flex:1 1 auto; min-height:0;
156	    display:flex; align-items:center; justify-content:center;
157	    padding:clamp(8px,2vh,24px) clamp(10px,3vw,40px);
158	    position:relative; z-index:1;
159	  }
160	  .viewer{
161	    display:flex; align-items:center; justify-content:center;
162	    gap:clamp(8px,2.5vw,28px);
163	    width:100%;
164	    max-width:1040px;
165	  }
166	
167	  .arrow{
168	    flex:0 0 auto;
169	    width:clamp(34px,5vw,46px); height:clamp(34px,5vw,46px);
170	    border-radius:50%;
171	    background:rgba(20,16,14,.55);
172	    color:var(--c-white);
173	    border:1px solid rgba(247,241,230,.4);
174	    font-size:1.35rem; line-height:1;
175	    display:flex; align-items:center; justify-content:center;
176	    cursor:pointer;
177	    transition:background .15s ease, color .15s ease, transform .15s ease;
178	  }
179	  .arrow:hover, .arrow:focus-visible{
180	    background:var(--c-gold); color:var(--c-black); transform:scale(1.06);
181	  }
182	  .arrow:disabled{
183	    opacity:.35; cursor:default; pointer-events:none;
184	  }
185	
186	  .image-frame{
187	    position:relative;
188	    min-width:0;              /* let this flex item actually shrink instead of overflowing */
189	    width:fit-content;
190	    max-width:100%;           /* real size cap lives on .img-el below */
191	    background:var(--c-white);
192	    padding:12px 12px 0;
193	    border-radius:8px;
194	    box-shadow:0 22px 55px rgba(0,0,0,.4);
195	  }
196	
197	  /* little postage-stamp accent — purely decorative */
198	  .stamp{
199	    position:absolute; top:-10px; right:-10px;
200	    width:36px; height:44px;
201	    background:var(--c-white);
202	    border:3px dashed var(--c-gold);
203	    border-radius:2px;
204	    display:flex; flex-direction:column; align-items:center; justify-content:center;
205	    gap:2px;
206	    transform:rotate(6deg);
207	    box-shadow:0 6px 14px rgba(0,0,0,.25);
208	  }
209	  .stamp svg{ width:16px; height:16px; stroke:var(--c-red); fill:none; stroke-width:1.6; }
210	  .stamp span{ font-size:.5rem; letter-spacing:.06em; color:var(--c-red); font-weight:700; }
211	
212	  /* img-wrap is sized BY its child (the img), not the other way round —
213	     this is what keeps the placeholder from drifting outside the postcard
214	     border on narrow screens (a div with its own aspect-ratio box can
215	     render wider than its flex parent; a replaced element like <img>
216	     can't, so we let the <img>'s own box drive the wrapper's size). */
217	  .img-wrap{
218	    position:relative;
219	    display:inline-block;
220	    max-width:100%;
221	    border-radius:4px;
222	    overflow:hidden;
223	  }
224	  .img-el{
225	    position:relative; z-index:1;
226	    display:block;
227	    width:auto; height:auto;
228	    aspect-ratio:3/2;
229	    /* EDIT: these two lines control the displayed photo size */
230	    max-width:min(66vw,760px);
231	    max-height:min(64vh,600px);
232	    object-fit:cover;
233	    opacity:1;
234	    transition:opacity .18s ease;
235	  }
236	  .img-el.is-hidden{ opacity:0; }
237	
238	  .placeholder-fill{
239	    position:absolute; inset:0; z-index:0;
240	    display:flex; flex-direction:column; align-items:center; justify-content:center;

