input.new_string:
/* ---------- postcard back ---------- */

function postmarkFor(id){
  const meta = PHOTO_META[id] || {};
  return {
    place: meta.place || POSTMARK_PLACE[state.gallery] || "",
    date: meta.date || ""
  };
}

/* ISO (YYYY-MM-DD) -> DD.MM.YYYY, the way a German postmark reads.
   Anything else — including the "" that unfilled dates carry —
   comes back empty, and the postmark just shows no date line. */
function formatPostmarkDate(iso){
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(iso || "");
  return m ? m[3] + "." + m[2] + "." + m[1] : "";
}

/* Both faces stay in the DOM, so aria-hidden is what actually keeps
   a screen reader from reading the hidden side of the card. */
function setFlipped(flipped){
  state.flipped = !!flipped;
  const pc = dict().ui.postcard;
  els.frame.classList.toggle("is-flipped", state.flipped);
  els.postcardFront.setAttribute("aria-hidden", String(state.flipped));
  els.postcardBack.setAttribute("aria-hidden", String(!state.flipped));
  els.flipBtn.setAttribute("aria-pressed", String(state.flipped));
  els.flipBtn.setAttribute("aria-label", state.flipped ? pc.turnBack : pc.turn);
