input.new_string:
document.addEventListener("click", function(){ closeAllDropdowns(); });
document.addEventListener("keydown", function(e){
  if (e.key === "Escape"){
    if (state.flipped) setFlipped(false);
    closeAllDropdowns();
  }
  if (e.key === "ArrowLeft") stepImage(-1);
  if (e.key === "ArrowRight") stepImage(1);
  if (e.key === " " || e.key === "Enter"){
    /* Buttons (nav, arrows, the flip control itself) keep their own
       native activation — only a keypress on the bare page turns the
       card. The page can't scroll anyway, but preventDefault keeps
       Space from doing anything else surprising. */
    const t = e.target;
    if (t && t.closest && t.closest("button")) return;
    e.preventDefault();
    toggleFlip();
  }
});

/* --- postcard flip wiring --- */
els.postcard.addEventListener("click", toggleFlip);
els.flipBtn.addEventListener("click", toggleFlip);

