input.new_string:
.img-el{
  position:relative; z-index:1;
  display:block;
  width:auto; height:auto;
  /* NO forced aspect-ratio, and contain rather than cover. The photos
     are a mix of portrait (3:4), landscape (4:3) and square; the old
     fixed 3/2 + object-fit:cover centre-crop cut the top and bottom
     off every portrait one — heads included. Each photo now shows
     whole and the postcard resizes around it. Per-photo shape comes
     from PHOTO_META's w/h, which showImage() sets as an inline
     aspect-ratio so the box is right before the file loads. */
  /* EDIT: these two lines control the displayed photo size */
  max-width:min(66vw,760px);
  max-height:min(64vh,600px);
  object-fit:contain;
  opacity:1;
  transition:opacity .18s ease;
}
.img-el.is-hidden{ opacity:0; }
/* An <img> with no src has no intrinsic size, so a slot still waiting
   for its photo needs a box of its own for the placeholder to fill. */
.img-el.is-empty{
  aspect-ratio:3/2;
  width:min(66vw,760px);
}

