function showImage(media, altText, note){
  els.placeholderText.textContent = note;
  if (media && media.src){
    els.image.classList.add("is-hidden");
    requestAnimationFrame(function(){
      els.image.alt = altText;
      els.image.src = media.src;
    });
  } else {
    els.image.removeAttribute("src");
    els.image.alt = altText;
    els.image.classList.add("is-hidden");
  }
}

input.new_string:
function showImage(media, altText, note, meta){
  els.placeholderText.textContent = note;
  /* Shape the box from the known file dimensions before the photo
     arrives, so the card doesn't resize twice on every navigation.
     Empty string hands sizing back to the CSS (see .img-el.is-empty). */
  els.image.style.aspectRatio = (meta && meta.w && meta.h)
    ? meta.w + " / " + meta.h
    : "";
  if (media && media.src){
    els.image.classList.remove("is-empty");
    els.image.classList.add("is-hidden");
    requestAnimationFrame(function(){
      els.image.alt = altText;
      els.image.src = media.src;
    });
  } else {
    els.image.removeAttribute("src");
    els.image.classList.add("is-empty");
    els.image.alt = altText;
    els.image.classList.add("is-hidden");
  }
}

