input.old_string:
/* Size the box from the known file dimensions BEFORE the photo
   arrives. These have to be the width/height content attributes,
   not an inline aspect-ratio: the attributes give the <img> real
   intrinsic dimensions, which width:auto/height:auto then resolve
   against and the max-width/max-height caps scale down in
   proportion. An aspect-ratio alone leaves the element with no
   intrinsic width, so the card collapses to nothing until the file
   lands — and stays collapsed if it 404s, hiding the placeholder.
   Photos are separate files now, so this matters. */
if (meta && meta.w && meta.h){
  els.image.setAttribute("width", meta.w);
  els.image.setAttribute("height", meta.h);
} else {
  els.image.removeAttribute("width");
  els.image.removeAttribute("height");
}
if (media && media.src){
  els.image.classList.remove("is-empty");
  els.image.classList.add("is-hidden");

