   the card is the right size and shape from the first frame instead
   of growing into place once the image arrives. Clearing it falls
   back to the 3:2 placeholder shape. */
if (meta && meta.w && meta.h){
  els.image.style.setProperty("--ar", meta.w / meta.h);
} else {
  els.image.style.removeProperty("--ar");
}
if (media && media.src){
  els.image.classList.add("is-hidden");

