const res={};
const frame=document.getElementById('imageFrame'), card=document.getElementById('postcard');
const front=document.getElementById('postcardFront'), back=document.getElementById('postcardBack');
res.before={flipped:frame.classList.contains('is-flipped'), frontHidden:front.getAttribute('aria-hidden'), backHidden:back.getAttribute('aria-hidden'), transform:getComputedStyle(card).transform.slice(0,30)};
card.click();
res.afterClick={flipped:frame.classList.contains('is-flipped'), frontHidden:front.getAttribute('aria-hidden'), backHidden:back.getAttribute('aria-hidden'), pressed:document.getElementById('flipBtn').getAttribute('aria-pressed'), label:document.getElementById('flipBtn').getAttribute('aria-label')};
// back face must exactly cover the front
const fr=front.getBoundingClientRect(), br=back.getBoundingClientRect();
res.backCoversFront = (Math.round(fr.width)===Math.round(br.width) && Math.round(fr.height)===Math.round(br.height)) ? 'yes '+Math.round(br.width)+'x'+Math.round(br.height) : 'NO front='+Math.round(fr.width)+'x'+Math.round(fr.height)+' back='+Math.round(br.width)+'x'+Math.round(br.height);
res.preserve3d = getComputedStyle(card).transformStyle;
res.cardOverflow = getComputedStyle(card).overflow;
res.perspective = getComputedStyle(frame).perspective;
// navigating must land back on the photo side
document.getElementById('nextBtn').click();
res.afterNext={flipped:frame.classList.contains('is-flipped'), caption:document.getElementById('galleryCaption').textContent};
JSON.stringify(res,null,1);

