input.new_string:
/* A portrait photo makes a portrait card, and a portrait card can't
   carry a side-by-side divided back — both columns end up too narrow
   to read. Stack them instead: message on top, address row beneath.
   showImage() adds .is-portrait whenever the photo is taller than
   it is wide. (Before the photos became real files they were all
   cropped to 3:2 landscape, so this case didn't exist.) */
.image-frame.is-portrait .postcard-back{
  flex-direction:column;
  gap:clamp(6px,1.4vh,12px);
}
.image-frame.is-portrait .pc-message{ flex:1 1 auto; }
.image-frame.is-portrait .pc-split{
  flex:0 0 1px; width:100%;
  background:repeating-linear-gradient(90deg,
    var(--c-stone) 0 6px, transparent 6px 12px);
}
.image-frame.is-portrait .pc-address{
  flex:0 0 auto;
  flex-direction:row; align-items:flex-end;
  gap:clamp(8px,2vw,16px);
}
.image-frame.is-portrait .pc-lines{ flex:1 1 auto; margin-top:0; }
.image-frame.is-portrait .pc-stamp-zone{
  order:2;                /* stamp stays on the right, as on a real card */
  align-self:flex-start;
}

/* flip control — deliberately OUTSIDE .postcard so it never rotates */

